"""Write docs/TERRAIN_VALIDATION.md from the built terrain assets.

Run from backend/:  python -m terrain.report
"""

import json
from pathlib import Path

DATA = Path(__file__).resolve().parent.parent / "data" / "terrain"
DOC = Path(__file__).resolve().parents[2] / "docs" / "TERRAIN_VALIDATION.md"


def main():
    index = json.loads((DATA / "index.json").read_text())
    lines = [
        "# Terrain horizon validation",
        "",
        "Generated by `python -m terrain.report` from `backend/data/terrain/`.",
        "Tolerances were fixed before results were inspected "
        "(see `terrain/build.py`).",
        "",
        "| Site | Point (lat, lon E) | Registration median / p95 (m) "
        "| Convergence 1/2/10 m | Mean illumination @1 m 2024–25 "
        "| Result |",
        "|---|---|---|---|---|---|",
    ]
    details = []
    for site_id in sorted(index["sites"]):
        a = json.loads((DATA / f"{site_id}.json").read_text())
        c = a["validation"]["checks"]
        reg = c["registration"]
        conv = "/".join("pass" if v["pass"] else "FAIL"
                        for v in c["convergence"].values())
        pub = c["published_illumination"]
        lines.append(
            f"| {a['name']} ({a['pgda_site']}) "
            f"| {a['point']['latitude']:.5f}, {a['point']['longitude']:.5f} "
            f"| {reg['median_m']} / {reg['p95_abs_m']} | {conv} "
            f"| {pub['our_mean_solar_disk_fraction_1m']:.3f} (> 0.70 published) "
            f"| {'PASS' if a['validation']['passed'] else 'FAIL'} |"
        )
        details.append(f"\n## {a['name']} ({a['pgda_site']})\n")
        details.append(f"- Point source: {a['point']['source']}")
        details.append(f"- Ground height above 1737.4 km sphere: "
                       f"{a['surface_height_m']} m")
        details.append(f"- Coverage: {a['coverage']}")
        for h, v in c["convergence"].items():
            details.append(f"- Convergence at {h} m: {v}")
        hz = a["hazard"]["discs"]["100"]
        details.append(
            f"- Slope within 100 m (5 m pixels): median {hz['median_deg']}°,"
            f" p95 {hz['p95_deg']}°, {hz['pct_below_10']} % below 10°"
        )
        details.append(f"- Sources: {', '.join(a['sources'])}")
    lines.append("")
    lines.append("Unsupported sites (source DEM but no documented point):")
    lines += [f"- {v}" for v in index.get("unsupported", {}).values()]
    DOC.parent.mkdir(exist_ok=True)
    DOC.write_text("\n".join(lines + details) + "\n")
    print(f"wrote {DOC}")


if __name__ == "__main__":
    main()
